import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Refine a triangular-lattice seed by maximizing its minimum distance
    subject to diameter one, using deterministic full-coordinate SLSQP runs."""
    removed = {(2, 0), (-2, 2), (0, -2)}
    axial = [
        (q, r)
        for q in range(-2, 3)
        for r in range(-2, 3)
        if max(abs(q), abs(r), abs(q + r)) <= 2 and (q, r) not in removed
    ]
    seed = np.array(
        [(q + 0.5 * r, 0.5 * np.sqrt(3.0) * r) for q, r in axial],
        dtype=np.float64,
    )

    upper = np.triu_indices(16, 1)

    def normalize(points):
        delta = points[:, None, :] - points[None, :, :]
        diameter = np.sqrt(np.max(np.sum(delta * delta, axis=2)))
        return points / diameter

    def quality(points):
        delta = points[:, None, :] - points[None, :, :]
        d2 = np.sum(delta * delta, axis=2)[upper]
        return float(np.min(d2) / np.max(d2))

    # Translation is removed by fixing the first point at the origin.
    seed = normalize(seed - seed[0])
    best = seed
    best_value = quality(seed)

    try:
        from scipy.optimize import minimize

        def unpack(x):
            return np.vstack((np.zeros(2), x.reshape(15, 2)))

        def inequalities(z):
            points = unpack(z[:-1])
            delta = points[:, None, :] - points[None, :, :]
            d2 = np.sum(delta * delta, axis=2)[upper]
            # Every pair must lie between the common lower bound and
            # the unit diameter bound.
            return np.concatenate((d2 - z[-1] * z[-1], 1.0 - d2))

        rng = np.random.default_rng(16022026)
        starts = [seed]
        for scale in (0.003, 0.007, 0.012, 0.020):
            for _ in range(3):
                points = seed.copy()
                points[1:] += rng.normal(0.0, scale, size=(15, 2))
                points = normalize(points - points[0])
                starts.append(points)

        for points in starts:
            initial = np.r_[points[1:].ravel(), 0.23]
            result = minimize(
                lambda z: -z[-1],
                initial,
                method="SLSQP",
                bounds=[(-1.0, 1.0)] * 30 + [(0.0, 0.5)],
                constraints={"type": "ineq", "fun": inequalities},
                options={"maxiter": 900, "ftol": 1e-13, "disp": False},
            )
            candidate = normalize(unpack(result.x[:-1]))
            value = quality(candidate)
            if np.isfinite(value) and value > best_value:
                best = candidate
                best_value = value
    except Exception:
        pass

    return np.asarray(best, dtype=np.float64)


